<script>
  import{ACTION_OPTIONS,DUPLICATE_RECORDS_MISSION,VERDICT_OPTIONS,duplicateGroups,keyValue,sqlForDuplicateCheck}from'../lib/game/duplicate-records-mission.js';
  import { recordCompletion } from '../lib/game/progress.js';
  // Remembered, so the hub knows and closing the tab does not undo it.
  $: if (missionComplete) recordCompletion('duplicate-records');
  let caseIndex=0,step='key',selected='',checked=false,correct=false,queryRan=false,completed=[];
  $: caseRecord=DUPLICATE_RECORDS_MISSION.cases[caseIndex];$: missionComplete=completed.length===DUPLICATE_RECORDS_MISSION.cases.length;
  $: groups=caseRecord?duplicateGroups(caseRecord.rows,caseRecord.key,caseRecord.columns):[];$: sql=caseRecord?sqlForDuplicateCheck(caseRecord.table,caseRecord.key):'';
  $: options=caseRecord?(step==='key'?caseRecord.keyOptions.map(columns=>({value:keyValue(columns),label:columns.join(' + '),note:columns.length>1?'composite key':'single-column key'})):step==='verdict'?VERDICT_OPTIONS:ACTION_OPTIONS):[];
  $: answer=caseRecord?(step==='key'?keyValue(caseRecord.key):step==='verdict'?caseRecord.verdict:caseRecord.action):'';
  $: question=step==='key'?'Which field or field combination should be unique?':step==='verdict'?'What does the SQL result mean?':'What is the safe treatment?';
  $: theory=step==='key'?'A key identifies one row at the declared grain. A composite key uses multiple fields when no single field is sufficient.':step==='verdict'?'GROUP BY forms groups with matching key values; HAVING COUNT(*) > 1 keeps only repeated key groups.':'Detection is not permission to delete. Preserve lineage until the cause and authoritative record are established.';
  $: progress=Math.round(((completed.length*3+(step==='verdict'?1:step==='action'?2:0)+(correct?1:0))/(DUPLICATE_RECORDS_MISSION.cases.length*3))*100);
  function choose(value){if(correct)return;selected=value;checked=true;correct=value===answer}
  function advance(){if(!correct)return;if(step==='key'){queryRan=true;step='verdict'}else if(step==='verdict')step='action';else{completed=[...completed,caseRecord.id];caseIndex+=1;step='key';queryRan=false}selected='';checked=false;correct=false}
  function resetMission(){caseIndex=0;step='key';selected='';checked=false;correct=false;queryRan=false;completed=[]}
</script>
<svelte:head><title>Keys and Duplicate Records | Qubix University</title><meta name="description" content="Local AI draft of a Qubix Superstore SQL duplicate-detection mission."/></svelte:head>
<section class="mission-shell qx-shell"><header><div class="identity"><span class="role">PRE<br/>INTERN</span><div><p>{DUPLICATE_RECORDS_MISSION.id} · {DUPLICATE_RECORDS_MISSION.status}</p><h1>{DUPLICATE_RECORDS_MISSION.title}</h1></div></div><nav><a href="?mode=game&mission=table-grain">Mission 004</a><a href="?mode=game&mission=join-grain">Mission 006</a><a href="?mode=wiki">Library</a></nav></header><div class="progress" aria-label={`Mission ${progress}% complete`}><span style={`width:${progress}%`}></span></div>
  <main>
    <section class="sql-window"><div class="window-bar"><span class="dot red"></span><span class="dot amber"></span><span class="dot green"></span><b>Qubix SQL Data Quality Workbench</b><em>{missionComplete?'review complete':caseRecord.table}</em></div>
      {#if missionComplete}<div class="complete-screen"><span>✓</span><h2>Duplicate checks complete</h2><p>Six table keys documented and every repeated-key result treated without discarding evidence.</p></div>
      {:else}<div class="tabs"><span class:active={!queryRan}>Source data</span><span class:active={queryRan}>Duplicate check</span><span class:active={queryRan}>Results {groups.length?`(${groups.length})`:'(0)'}</span></div><div class="source-grid"><table><thead><tr>{#each caseRecord.columns as column}<th class:keycol={queryRan&&caseRecord.key.includes(column)}>{column}</th>{/each}</tr></thead><tbody>{#each caseRecord.rows as row}<tr>{#each row as value,columnIndex}<td class:keycol={queryRan&&caseRecord.key.includes(caseRecord.columns[columnIndex])}>{value}</td>{/each}</tr>{/each}</tbody></table></div><div class="editor"><div class="line-numbers">1<br/>2<br/>3<br/>4</div><pre>{queryRan?sql:'-- Choose the key fields to generate a duplicate check.'}</pre></div>{#if queryRan}<div class="results"><div class="result-head">QUERY RESULT · {groups.length} REPEATED KEY {groups.length===1?'GROUP':'GROUPS'}</div>{#if groups.length}<table><thead><tr>{#each caseRecord.key as column}<th>{column}</th>{/each}<th>row_count</th></tr></thead><tbody>{#each groups as group}<tr>{#each group.values as value}<td>{value}</td>{/each}<td class="bad">{group.row_count}</td></tr>{/each}</tbody></table>{:else}<p>0 rows — no key combination occurs more than once.</p>{/if}</div>{/if}{/if}
    </section>
    <aside class="lesson-card">{#if missionComplete}<div class="completion"><span>✓</span><p class="eyebrow">COMPETENCY DEMONSTRATED</p><h2>Evidence preserved</h2><p>{DUPLICATE_RECORDS_MISSION.competency}</p><ul>{#each DUPLICATE_RECORDS_MISSION.cases as item}<li><b>{item.table}</b><span>{item.key.join(' + ')}</span><em>{item.verdict==='duplicate-key'?'violation':'clean'}</em></li>{/each}</ul><button on:click={resetMission}>Run mission again</button></div>
      {:else}<div class="case-meta"><span>TABLE {caseIndex+1} OF {DUPLICATE_RECORDS_MISSION.cases.length}</span><span>DECISION {step==='key'?1:step==='verdict'?2:3} OF 3</span></div><p class="eyebrow">THEORY → PRACTICAL · {step.toUpperCase()}</p><h2>{question}</h2><p class="theory">{theory}</p><article class="context">{caseRecord.context}</article><div class="options">{#each options as option}<button class:selected={selected===option.value} class:right={correct&&selected===option.value} class:wrong={checked&&!correct&&selected===option.value} on:click={()=>choose(option.value)} disabled={correct}><b>{option.label}</b><span>{option.note}</span></button>{/each}</div>{#if checked}<div class:success={correct} class:retry={!correct} class="feedback" role="status">{#if correct}<b>Correct.</b> {step==='key'?caseRecord.keyExplanation:step==='verdict'?caseRecord.verdictExplanation:caseRecord.actionExplanation}{:else}<b>Try again.</b> Start from the declared row grain and preserve evidence.{/if}</div>{/if}{#if correct}<button class="continue" on:click={advance}>{step==='key'?'Run SQL duplicate check':step==='verdict'?'Choose safe treatment':caseIndex===DUPLICATE_RECORDS_MISSION.cases.length-1?'Complete mission':'Open next table'} →</button>{/if}{/if}
    </aside>
  </main><footer><span>Source-informed learning draft · accessed 21 August 2026</span><span>{#each DUPLICATE_RECORDS_MISSION.sources as source,index}<a href={source.url} target="_blank" rel="noreferrer">{source.label}</a>{index<DUPLICATE_RECORDS_MISSION.sources.length-1?' · ':''}{/each}</span></footer>
</section>
<style>
  :global(html),:global(body){overflow:auto;background:#151515}:global(body){position:static}.mission-shell{min-height:100vh;max-width:none;padding:18px clamp(12px,3vw,34px) 30px;background:radial-gradient(circle at 50% 0,#32302b,#151515 60%);overflow:auto;color:#f1ede4}header{max-width:1340px;margin:0 auto 14px;display:flex;align-items:center;justify-content:space-between;gap:16px}.identity{display:flex;align-items:center;gap:12px}.role{display:grid;place-items:center;width:48px;height:48px;border-radius:13px;background:#a85a34;color:white;font:900 9px/1.15 var(--qx-font);text-align:center}.identity p{margin:0 0 3px;color:#aaa295;font:800 9px var(--qx-font);letter-spacing:.1em}.identity h1{margin:0;color:white;font:700 26px Georgia,serif}nav{display:flex;gap:14px}nav a,footer a{color:#e2c7b7;font:800 11px var(--qx-font);text-decoration:none;border-bottom:1px solid currentColor;padding-bottom:3px}.progress{max-width:1340px;height:5px;margin:0 auto 16px;border-radius:8px;background:rgba(255,255,255,.1);overflow:hidden}.progress span{display:block;height:100%;background:#63b13b;transition:width .35s ease}main{max-width:1340px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1.35fr) minmax(360px,.65fr);gap:16px;align-items:start}.sql-window,.lesson-card{border:1px solid rgba(255,255,255,.14);border-radius:16px;overflow:hidden}.sql-window{min-height:690px;background:#f4f1ea;color:#25231f}.window-bar{height:43px;padding:0 14px;display:flex;align-items:center;gap:7px;background:#2b2c2b;color:#d9d7d1}.dot{width:10px;height:10px;border-radius:50%}.red{background:#df5a4c}.amber{background:#e0ad42}.green{background:#61a94a}.window-bar b{margin-left:7px;font:800 10px var(--qx-font)}.window-bar em{margin-left:auto;color:#999;font:700 9px var(--qx-font)}.tabs{display:flex;background:#ddd9d0;border-bottom:1px solid #bbb5a8}.tabs span{padding:10px 14px;color:#6e675a;font:800 9px var(--qx-font);border-right:1px solid #bbb5a8}.tabs span.active{background:#f4f1ea;color:#25231f}.source-grid{padding:14px;overflow-x:auto}.source-grid table,.results table{width:100%;border-collapse:collapse;white-space:nowrap}.source-grid th,.source-grid td,.results th,.results td{padding:8px 10px;border:1px solid #d2ccc0;text-align:left;font:700 9.5px var(--qx-font)}.source-grid th,.results th{background:#e5e0d6;color:#514a3f}.source-grid .keycol{background:#f4e5d8}.editor{min-height:126px;display:grid;grid-template-columns:36px 1fr;background:#1f2328;color:#d9e2ec;border-block:1px solid #111}.line-numbers{padding:14px 10px;color:#69717a;background:#191c20;text-align:right;font:500 11px/1.65 monospace}.editor pre{margin:0;padding:14px;white-space:pre-wrap;color:#b9d7f1;font:600 11.5px/1.65 Consolas,monospace}.results{padding:14px}.result-head{margin-bottom:8px;color:#6d6558;font:900 8.5px var(--qx-font);letter-spacing:.1em}.results .bad{color:#a52f21;background:#f7ded9;font-weight:900}.results p{margin:0;padding:14px;border:1px solid #cbd9bf;background:#eaf1e4;color:#41632d;font:800 11px var(--qx-font)}.lesson-card{padding:clamp(18px,2.4vw,28px);background:#f1ede4;color:#25231f;overflow:visible}.case-meta{display:flex;justify-content:space-between;margin-bottom:15px;color:#716958;font:900 8.5px var(--qx-font);letter-spacing:.08em}.eyebrow{margin:0 0 7px;color:#8c4c2e;font:900 9px var(--qx-font);letter-spacing:.12em}.lesson-card h2,.completion h2{margin:0;font:700 23px Georgia,serif}.theory,.completion>p{margin:8px 0 14px;color:#625a49;font:600 12px/1.5 var(--qx-font)}.context{margin-bottom:13px;padding:12px;border:1px solid #d8d0be;border-radius:10px;background:#fbf8f1;font:650 11.5px/1.45 var(--qx-font)}.options{display:grid;gap:8px}.options button{min-height:59px;padding:10px 12px;border:2px solid #ded6c6;border-radius:11px;background:white;color:#25231f;text-align:left;cursor:pointer}.options button b,.options button span{display:block}.options button b{font:850 11.5px/1.3 var(--qx-font)}.options button span{margin-top:4px;color:#736a59;font:600 9.5px/1.3 var(--qx-font)}.options button:hover,.options button.selected{border-color:#a85a34}.options button.right{border-color:#559535;background:#e7f0df}.options button.wrong{border-color:#b83a29;background:#f6ddd8}.options button:focus-visible,.continue:focus-visible,.completion button:focus-visible{outline:3px solid #a85a34;outline-offset:2px}.options button:disabled{cursor:default}.feedback{margin-top:11px;padding:11px 12px;border-radius:10px;font:650 11.5px/1.45 var(--qx-font)}.feedback.success{background:#e7f0df;color:#3d6529}.feedback.retry{background:#f6ddd8;color:#912c1e}.continue,.completion button{width:100%;min-height:46px;margin-top:11px;border:0;border-radius:11px;background:#a85a34;color:white;font:900 11.5px var(--qx-font);cursor:pointer}.completion{text-align:center}.completion>span,.complete-screen>span{display:grid;place-items:center;width:58px;height:58px;margin:10px auto 14px;border-radius:50%;background:#559535;color:white;font:900 26px var(--qx-font)}.completion ul{list-style:none;margin:20px 0 0;padding:0;border:1px solid #d8d0be;border-radius:11px;overflow:hidden;text-align:left}.completion li{display:grid;grid-template-columns:95px 1fr 55px;gap:8px;padding:10px;border-bottom:1px solid #ddd5c5;font:700 9.5px var(--qx-font)}.completion li:last-child{border-bottom:0}.completion li span{color:#6f6758}.completion li em{color:#8c4c2e;text-align:right}.complete-screen{display:grid;place-content:center;min-height:640px;padding:30px;text-align:center}.complete-screen h2{margin:0;font:700 27px Georgia,serif}.complete-screen p{max-width:480px;color:#625a49;font:600 12.5px/1.5 var(--qx-font)}footer{max-width:1340px;margin:14px auto 0;display:flex;justify-content:space-between;gap:14px;color:#918a7d;font:650 9px/1.5 var(--qx-font)}footer a{font-size:9px}@media(max-width:940px){main{grid-template-columns:1fr}.sql-window{min-height:0}footer{flex-direction:column}}@media(max-width:600px){.mission-shell{padding:13px 10px 25px}header{align-items:flex-start}.identity h1{font-size:20px}.role{width:42px;height:42px}nav{flex-direction:column;align-items:flex-end;gap:6px}.sql-window{border-radius:12px}.window-bar b{max-width:150px}.source-grid{padding:9px}.lesson-card{padding:16px}.completion li{grid-template-columns:1fr}.complete-screen{min-height:400px}}@media(prefers-reduced-motion:reduce){.progress span{transition:none}}
</style>
